class Solution { fun largestMagicSquare(grid:Array<IntArray>):Int{val rows=grid.size;val cols=grid[0].size;val rowPrefix=Array(rows){IntArray(cols+1)};val colPrefix=Array(rows+1){IntArray(cols)};for(r in 0 until rows)for(c in 0 until cols){rowPrefix[r][c+1]=rowPrefix[r][c]+grid[r][c];colPrefix[r+1][c]=colPrefix[r][c]+grid[r][c]};for(size in minOf(rows,cols) downTo 1)for(top in 0..rows-size)for(left in 0..cols-size){val target=rowPrefix[top][left+size]-rowPrefix[top][left];var valid=true;for(offset in 0 until size)if(rowPrefix[top+offset][left+size]-rowPrefix[top+offset][left]!=target||colPrefix[top+size][left+offset]-colPrefix[top][left+offset]!=target){valid=false;break};var first=0;var second=0;for(offset in 0 until size){first+=grid[top+offset][left+offset];second+=grid[top+offset][left+size-1-offset]};if(valid&&first==target&&second==target)return size};return 1} }
